-- =============================================================================
-- Tenant Administrator Avatar Template
--
-- Seeds the system-tenant template row in ores_assets_images_tbl for a
-- provisioned tenant administrator's picture, vendored at
-- external/acme/tenant_admin_avatar.png. The source sheet carried both
-- administrator badges; the vendored picture is the tenant badge alone,
-- cropped to its circle. The provisioning step's attach_photos copies it into
-- the tenant and saves it on the account it created. Idempotent: skips if a
-- system-tenant row with this key already exists.
-- =============================================================================

DO $$
BEGIN
    if not exists (
        select 1 from ores_assets_images_tbl
        where tenant_id = ores_utility_system_tenant_id_fn()
          and code = 'tenant_admin_avatar'
          and valid_to = ores_utility_infinity_timestamp_fn()
    ) then
        insert into ores_assets_images_tbl (
            id, tenant_id, version, code, description, mime_type, data,
            modified_by, performed_by, change_reason_code, change_commentary
        ) values (
            gen_random_uuid(), ores_utility_system_tenant_id_fn(), 0,
            'tenant_admin_avatar', 'Tenant administrator avatar (ORE Studio)',
            'image/png',
            $b64$$b64$,
            coalesce(ores_iam_current_service_fn(), current_user), current_user,
            'system.external_data_import',
            'Vendored from external/acme/tenant_admin_avatar.png (tenant badge cropped from the source sheet)'
        );
    end if;
END $$;
